def map_request_status_outcome(result: dict[str, object]) -> OutcomeStatus:
    if not result.get("success"):
        return OutcomeStatus.UNKNOWN
    state_value = str(result.get("state") or "unknown")
    if state_value == "completed":
        return OutcomeStatus.SUCCEEDED
    if state_value == "running_after_timeout":
        return OutcomeStatus.TIMED_OUT
    if state_value in {"queued", "running", "unknown", "completed_after_cancel_request"}:
        return OutcomeStatus.UNKNOWN
    if state_value in {"expired", "not_found"}:
        return OutcomeStatus.CONDITION_FALSE
    return OutcomeStatus.UNKNOWN


